package br.com.admeclesial.application.relatorio;
import br.com.admeclesial.application.usuario.SegurancaOrganizacaoService; import br.com.admeclesial.infrastructure.persistence.organizacao.OrganizacaoEclesialRepository; import br.com.admeclesial.infrastructure.persistence.projeto.*; import org.springframework.data.domain.PageRequest; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.math.BigDecimal;
@Service public class RelatorioProjetoApplicationService { final ProjetoRepository projetos; final FonteRecursoProjetoRepository fontes; final UtilizacaoRecursoRepository usos; final OrganizacaoEclesialRepository orgs; final SegurancaOrganizacaoService seguranca;
 public RelatorioProjetoApplicationService(ProjetoRepository p,FonteRecursoProjetoRepository f,UtilizacaoRecursoRepository u,OrganizacaoEclesialRepository o,SegurancaOrganizacaoService s){projetos=p;fontes=f;usos=u;orgs=o;seguranca=s;}
 @Transactional(readOnly=true) public RelatorioPagina<RelatorioProjetoItem> pesquisar(RelatorioProjetoFiltro f){var org=validar(f);boolean financeiro=exibirFinanceiro();var page=projetos.pesquisarRelatorio(org.getId(),f.tipo(),f.status(),f.inicio(),f.fim(),f.somenteRecursoSemUtilizacao(),PageRequest.of(pagina(f),tamanho(f)));var itens=page.getContent().stream().map(p->{var a=nvl(fontes.sumValorAlocadoPorProjeto(p.getId()));var u=nvl(usos.sumValorUtilizadoPorProjeto(p.getId()));return new RelatorioProjetoItem(p.getUuid(),p.getNome(),p.getTipo(),p.getStatus(),p.getDataInicio(),p.getDataFim(),financeiro?p.getValorEstimado():null,financeiro?a:null,financeiro?u:null,financeiro?a.subtract(u):null,a.signum()>0&&u.signum()==0,financeiro);}).toList();return new RelatorioPagina<>(itens,pagina(f),tamanho(f),page.getTotalElements(),page.getTotalPages(),"status,dataInicio","asc,desc");}
 @Transactional(readOnly=true) public RelatorioProjetoResumo resumo(RelatorioProjetoFiltro f){var org=validar(f);boolean financeiro=exibirFinanceiro();var all=projetos.pesquisarRelatorio(org.getId(),f.tipo(),f.status(),f.inicio(),f.fim(),f.somenteRecursoSemUtilizacao(),PageRequest.of(0,10000));BigDecimal a=BigDecimal.ZERO,u=BigDecimal.ZERO;if(financeiro)for(var p:all){a=a.add(nvl(fontes.sumValorAlocadoPorProjeto(p.getId())));u=u.add(nvl(usos.sumValorUtilizadoPorProjeto(p.getId())));}return new RelatorioProjetoResumo(all.getTotalElements(),financeiro?a:null,financeiro?u:null,financeiro?a.subtract(u):null,financeiro);}
 private br.com.admeclesial.domain.organizacao.OrganizacaoEclesial validar(RelatorioProjetoFiltro f){if(f.organizacaoUuid()==null)throw new IllegalArgumentException("Organização é obrigatória");if(f.inicio()!=null&&f.fim()!=null&&f.fim().isBefore(f.inicio()))throw new IllegalArgumentException("Período final não pode ser anterior ao inicial");seguranca.validarAcesso(f.organizacaoUuid());return orgs.findByUuid(f.organizacaoUuid()).orElseThrow();} private boolean exibirFinanceiro(){var a=SecurityContextHolder.getContext().getAuthentication();return a!=null&&a.getAuthorities().stream().anyMatch(x->x.getAuthority().equals("ROLE_ADMINISTRADOR")||x.getAuthority().equals("ROLE_FINANCEIRO"));} private int pagina(RelatorioProjetoFiltro f){return Math.max(0,f.pagina());} private int tamanho(RelatorioProjetoFiltro f){return Math.max(10,Math.min(100,f.tamanho()));} private BigDecimal nvl(BigDecimal v){return v==null?BigDecimal.ZERO:v;}
}
